define(["iCMS","bs-notify"],function(a){$(document);let e={init:function(a){a=$(a).addClass("js-notify-enabled");e.render(a)},notify:function(a){return $.notify({icon:a.icon||"",message:a.message,title:a.title||"",url:a.url||""},{element:a.element||"body",type:a.type||"info",placement:{from:a.from||"top",align:a.align||"right"},allow_dismiss:!1!==a.allow_dismiss,newest_on_top:!1!==a.newest_on_top,showProgressbar:!!a.show_progress_bar,offset:a.offset||20,spacing:a.spacing||10,z_index:a.z_index||1033,delay:a.delay||5e3,timer:a.timer||1e3,animate:{enter:a.animate_enter||"animated fadeIn",exit:a.animate_exit||"animated fadeOutDown"},template:`<div data-notify="container" class="col-11 col-sm-4 alert alert-{0} alert-dismissible" role="alert">
                    <div class="mb-0">
                      <span data-notify="icon"></span>
                      <span data-notify="title">{1}</span>
                      <span data-notify="message">{2}</span>
                    </div>
                    <div class="progress" data-notify="progressbar">
                      <div class="progress-bar progress-bar-{0}" role="progressbar" aria-valuenow="0" aria-valuemin="0" aria-valuemax="100" style="width: 0%;"></div>
                    </div>
                    <a href="{3}" target="{4}" data-notify="url"></a>
                    <a class="p-2 m-1 text-dark" href="javascript:void(0)" aria-label="Close" data-notify="dismiss">
                      <i class="fa fa-times"></i>
                    </a>
                  </div>`})},render:function(a){a.on("click",a=>{a=$(a.currentTarget).data();e.notify(a)})}};return e});